import json,sys,urllib.request,secrets,time
U='http://127.0.0.1:8088/ditto/api/2/things/'
def get(t,f='features'):
    return json.load(urllib.request.urlopen(U+'team040.mine:'+t+'?fields='+f))
def fv(t,k):
    return get(t)['features'].get(k,{}).get('properties',{}).get('value')
def send(typ,target,extra=None):
    run=fv('shift','idSimulationRun')
    cid='c-'+secrets.token_hex(16)
    body={'command_id':cid,'type':typ,'target':target,'run':run}
    if extra: body.update(extra)
    r=urllib.request.Request(U+'team040.mine:shift/inbox/messages/command?timeout=0',data=json.dumps(body).encode(),headers={'Content-Type':'application/json'},method='POST')
    st=urllib.request.urlopen(r).status
    for _ in range(20):
        time.sleep(1)
        for c in fv('shift','commands') or []:
            if c.get('id')==cid: print('HTTP',st,'ack',json.dumps(c,ensure_ascii=False)); return
    print('HTTP',st,'no ack')
if __name__=='__main__':
    send(sys.argv[1],sys.argv[2],json.loads(sys.argv[3]) if len(sys.argv)>3 else None)
EOF
